head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[tabControl > P > alwaysShowCloseBtn]<br/>closable 속성이 true 로 적용된 Tab 버튼에서 '닫기' 버튼을 항상 표시할지 설정합니다.",
    "validation" : [
        "closable 속성이 false 로 적용된 Tab 버튼은 '닫기' 버튼이 표시되지 않습니다.",
        "미설정 또는 false 설정 시 closable 속성이 true 로 적용된 Tab 버튼 영역에 마우스 오버 시 '닫기' 버튼이 표시됩니다.",
        "true 설정 시 closable 속성이 true 로 적용된 Tab 버튼에서 '닫기' 버튼이 항상 표시됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정   
    let properties = {
        alwaysShowCloseBtn : con_alwaysShowCloseBtn.getText(),
        closable: con_closable.getText(),
    };

    let cList = $c.gcm.createCList(properties);      
    let eList = $c.gcm.createEList(["onbeforetabclose"]);

    let grp_comp = $c.gcm.getTestGroup();    
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:tabControl ' + strNameSpace + ' ' + cList + ' ' + eList + ' id="" style="width:500px;height:200px;">';
    strTarget += '<w2:tabs disabled="false" style="height:40px;" id="tabs1" label="Tabs1"></w2:tabs>';
    strTarget += '<w2:tabs disabled="false" style="height:40px" id="tabs2" label="Tabs2"></w2:tabs>';
    strTarget += '<w2:tabs disabled="false" style="height:40px" id="tabs3" label="Tabs3"></w2:tabs>';
    strTarget += '<w2:content style="height:160px;" id="content1">';
    strTarget += '<w2:button style="width:80px; height:23px; " id="" label="tabs1"></w2:button>';
    strTarget += '</w2:content>';
    strTarget += '<w2:content style="height:160px" id="content2">';
    strTarget += '<xf:input id="" style="width:144px; height:21px; " initValue="tabs2"></xf:input>';
    strTarget += '</w2:content>';
    strTarget += '<w2:content style="height:160px" id="content3">';    
    strTarget += '</w2:content>';
    strTarget += '</w2:tabControl>';

    $c.gcm.createLabel('label="alwaysShowCloseBtn=false 인 경우는 닫기 버튼에 마우스 오버 후 클릭하여 확인"', '', 'label1');

    // target 생성    
    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "tabControl",
        strTarget,
        grp_comp
    );    
}



scwin.btn_getCloseBtn_onclick = function (e) {
    let closeButton1 = document.querySelector('div[id*=target1_tab_tabs1_close]');
    let closeButton2 = document.querySelector('div[id*=target1_tab_tabs2_close]');
    let closeButton3 = document.querySelector('div[id*=target1_tab_tabs3_close]');

    if (closeButton1)
        closeButtonDisplay1 = getComputedStyle(closeButton1).display;

    if (closeButton2)
        closeButtonDisplay2 = getComputedStyle(closeButton2).display;

    if (closeButton3)
        closeButtonDisplay3 = getComputedStyle(closeButton3).display;   

    wf_body_bottom.getObj("scwin").setReturnValue("closeButton1 display : " + closeButtonDisplay1);
    wf_body_bottom.getObj("scwin").setReturnValue("closeButton2 display : " + closeButtonDisplay2);
    wf_body_bottom.getObj("scwin").setReturnValue("closeButton3 display : " + closeButtonDisplay3);
}



scwin.target1_onbeforetabclose = function (tabId, index) {
    scwin.btn_getCloseBtn_onclick();
}
